//! SHA-512 compression: hand-scheduled Thumb-2 assembly on ARM (`compress_asm.s`, generated by `gen.py`),
//! the portable FIPS 180-4 compression elsewhere (host tests compare the two shapes through KATs).
#![no_std]
#[cfg(target_arch = "arm")]
core::arch::global_asm!(include_str!("compress_asm.s"), options(raw));
#[cfg(target_arch = "arm")]
extern "C" {
    fn pqsigner_sha512_compress_m33(state: *mut u64, block: *const u64);
}
/// One SHA-512 compression of `block` (16 decoded big-endian words) into `state`.
#[inline]
pub fn compress(state: &mut [u64; 8], block: &[u64; 16]) {
    #[cfg(target_arch = "arm")]
    // SAFETY: `state` is 8 writable u64 and `block` 16 readable u64 for the call; the routine follows
    // the AAPCS (callee-saved r4-r11 restored) and touches only its own stack frame besides them.
    unsafe {
        pqsigner_sha512_compress_m33(state.as_mut_ptr(), block.as_ptr())
    };
    #[cfg(not(target_arch = "arm"))]
    portable::compress(state, block);
}
#[cfg(not(target_arch = "arm"))]
mod portable {
    include!("portable.rs");
}
